:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --disabled: #4a4a6a;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 2rem;
  margin-bottom: 16px;
  color: var(--primary);
  letter-spacing: 2px;
}

.game-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

canvas {
  background: var(--accent);
  border-radius: 8px;
  image-rendering: pixelated;
  width: 200px;
  height: 200px;
}

.word-display {
  font-size: 1.8rem;
  letter-spacing: 8px;
  font-weight: bold;
  min-height: 2.2rem;
  font-family: monospace;
}

.message {
  font-size: 1.2rem;
  min-height: 1.8rem;
  color: var(--primary);
  font-weight: bold;
}

.letters {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  width: 100%;
  max-width: 420px;
}

.letters button {
  background: var(--accent);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 6px;
  padding: 10px 0;
  font-size: 1rem;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  min-height: 44px;
}

.letters button:hover:not(:disabled) {
  background: var(--primary);
}

.letters button:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.letters button:active:not(:disabled) {
  transform: scale(0.95);
}

.letters button:disabled {
  background: var(--disabled);
  color: #888;
  cursor: not-allowed;
  opacity: 0.7;
}

.new-game {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 12px 32px;
  font-size: 1.1rem;
  font-family: var(--font);
  font-weight: bold;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-height: 48px;
}

.new-game:hover {
  background: #c73650;
}

.new-game:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.new-game:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .letters {
    grid-template-columns: repeat(6, 1fr);
    gap: 6px;
  }
  .letters button {
    font-size: 0.9rem;
    padding: 8px 0;
  }
  .word-display {
    font-size: 1.4rem;
    letter-spacing: 5px;
  }
  .game-card {
    padding: 16px;
  }
}

const WORDS = ['JAVASCRIPT', 'PIXEL', 'HANGMAN', 'CANVAS', 'BROWSER', 'KEYBOARD', 'DESIGN', 'COLOR', 'BUTTON', 'SCREEN', 'GAME', 'CODE', 'STYLE', 'FONT', 'GRID'];
const MAX_WRONG = 6;

const canvas = document.getElementById('hangman-canvas');
const ctx = canvas.getContext('2d');
const wordDisplay = document.getElementById('word-display');
const messageEl = document.getElementById('message');
const lettersEl = document.getElementById('letters');
const newGameBtn = document.getElementById('new-game');

let word = '';
let guessed = new Set();
let wrongCount = 0;
let gameOver = false;

function initGame() {
  word = WORDS[Math.floor(Math.random() * WORDS.length)];
  guessed.clear();
  wrongCount = 0;
  gameOver = false;
  messageEl.textContent = '';
  renderWord();
  drawHangman();
  buildLetterButtons();
}

function renderWord() {
  wordDisplay.textContent = word.split('').map(ch => guessed.has(ch) ? ch : '_').join(' ');
}

function drawHangman() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = '#eaeaea';
  ctx.lineWidth = 4;
  ctx.lineCap = 'round';

  // Gallows (always drawn)
  ctx.beginPath();
  ctx.moveTo(40, 180);
  ctx.lineTo(160, 180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(100, 180);
  ctx.lineTo(100, 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(100, 40);
  ctx.lineTo(150, 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, 40);
  ctx.lineTo(150, 60);
  ctx.stroke();

  // Head
  if (wrongCount >= 1) {
    ctx.beginPath();
    ctx.arc(150, 75, 15, 0, Math.PI * 2);
    ctx.stroke();
  }
  // Body
  if (wrongCount >= 2) {
    ctx.beginPath();
    ctx.moveTo(150, 90);
    ctx.lineTo(150, 140);
    ctx.stroke();
  }
  // Left arm
  if (wrongCount >= 3) {
    ctx.beginPath();
    ctx.moveTo(150, 105);
    ctx.lineTo(125, 125);
    ctx.stroke();
  }
  // Right arm
  if (wrongCount >= 4) {
    ctx.beginPath();
    ctx.moveTo(150, 105);
    ctx.lineTo(175, 125);
    ctx.stroke();
  }
  // Left leg
  if (wrongCount >= 5) {
    ctx.beginPath();
    ctx.moveTo(150, 140);
    ctx.lineTo(130, 170);
    ctx.stroke();
  }
  // Right leg
  if (wrongCount >= 6) {
    ctx.beginPath();
    ctx.moveTo(150, 140);
    ctx.lineTo(170, 170);
    ctx.stroke();
  }
}

function buildLetterButtons() {
  lettersEl.innerHTML = '';
  for (let i = 65; i <= 90; i++) {
    const letter = String.fromCharCode(i);
    const btn = document.createElement('button');
    btn.textContent = letter;
    btn.setAttribute('aria-label', 'Guess letter ' + letter);
    btn.addEventListener('click', () => handleGuess(letter));
    if (guessed.has(letter) || gameOver) {
      btn.disabled = true;
    }
    lettersEl.appendChild(btn);
  }
}

function handleGuess(letter) {
  if (gameOver || guessed.has(letter)) return;
  guessed.add(letter);
  if (!word.includes(letter)) {
    wrongCount++;
  }
  renderWord();
  drawHangman();
  updateButtons();
  checkGameState();
}

function updateButtons() {
  const buttons = lettersEl.querySelectorAll('button');
  buttons.forEach(btn => {
    if (guessed.has(btn.textContent) || gameOver) {
      btn.disabled = true;
    }
  });
}

function checkGameState() {
  const won = word.split('').every(ch => guessed.has(ch));
  if (won) {
    gameOver = true;
    messageEl.textContent = 'You win! 🎉 The word was ' + word;
    updateButtons();
  } else if (wrongCount >= MAX_WRONG) {
    gameOver = true;
    messageEl.textContent = 'You lose! The word was ' + word;
    // Reveal all letters
    word.split('').forEach(ch => guessed.add(ch));
    renderWord();
    updateButtons();
  }
}

newGameBtn.addEventListener('click', initGame);

initGame();
